 f4:{grp:"4 terms",c:TEAL,name:"Grouping",hint:"pairs",when:"Four terms.",rule:"Group in pairs, factor each pair; the parentheses should match.",ex:[T("x<sup>3</sup> + 2x<sup>2</sup> + 3x + 6",["x<sup>2</sup>(x + 2) + 3(x + 2)","<b>(x + 2)(x<sup>2</sup> + 3)</b>"])]},
