/* ===== Fractions and decimals in every unit ===== */
const fr=(n,d)=>F(n,d), frs=(n,d)=>{ if(d<0){n=-n;d=-d;} const g=gcd(Math.abs(n),d)||1; n/=g; d/=g; return d===1?N(n):(n<0?"−":"")+FR(Math.abs(n),d); };
const dec=x=>N(+x.toFixed(4));
const FD=(u,html)=>{ u.learn+=`<h4>With fractions and decimals</h4>${html}`; };
const DEN=[2,3,4,5,6,8,10,12];
